+/*
+ * SPDX-License-Identifier: MIT
+ */
+/**
+ * Causal Log-Periodic Power Law (LPPL) fitting and normalized one-step
+ * prediction residual indicators. Start with
+ * {@link org.ta4j.core.indicators.lppl.LPPLResidualIndicator} for numeric
+ * composition and reuse its backing
+ * {@link org.ta4j.core.indicators.lppl.LPPLFitIndicator} when diagnostics are
+ * also required.
+ *
+ * @since 0.23.1
+ */
+package org.ta4j.core.indicators.lppl;
